#!/usr/bin/env python3
"""Seed pre-reading synthesis matrices with explicit curation-level evidence."""

from __future__ import annotations

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
MANIFEST = json.loads((ROOT / "survey_work" / "sources" / "papers.json").read_text())


def paper(prefix: str, label: str | None = None) -> str:
    matches = [item for item in MANIFEST if item["title"].startswith(prefix)]
    if len(matches) != 1:
        raise RuntimeError(f"Expected one paper for {prefix!r}, found {len(matches)}")
    item = matches[0]
    return f"[{label or item['title']}](../{item['folder']}/01_overview.md)"


def pair(a: tuple[str, str], b: tuple[str, str]) -> str:
    return f"{paper(*a)} / {paper(*b)}"


