def main() -> None:
    for name, table in MATRICES.items():
        path = ROOT / "synthesis" / name
        text = path.read_text()
        start = text.index("## Comparison Matrix")
        end = text.index("## Dependency and Evolution", start)
        replacement = f"## Comparison Matrix\n\n{NOTE}\n\n{table}\n\n"
        path.write_text(text[:start] + replacement + text[end:])
    print({"matrices_seeded": len(MATRICES)})


if __name__ == "__main__":
    main()
